mapper.select:
SELECT 
FROM QRCODE_SUPPLEMENT_REQUEST
WHERE CARD_ID = #{cardId,jdbcType=VARCHAR}
  AND TXN_SEQ = #{txnSeq,jdbcType=VARCHAR}
  AND ADVICE_OPT = #{adviceOpt,jdbcType=VARCHAR}

mapper.update:
UPDATE QRCODE_SUPPLEMENT_REQUEST
SET HANDLE_STATUS = #{handleStatus,jdbcType=VARCHAR},
    FAIL_REASON = #{failReason,jdbcType=VARCHAR},
    UPDATE_TIME = SYSDATE
WHERE CARD_ID = #{cardId,jdbcType=VARCHAR}
  AND TXN_SEQ = #{txnSeq,jdbcType=VARCHAR}
  AND ADVICE_OPT = #{adviceOpt,jdbcType=VARCHAR}
  AND HANDLE_STATUS = 'PENDING'

mapper.select:
SELECT * FROM (
    SELECT 
    FROM QRCODE_SUPPLEMENT_REQUEST
    WHERE HANDLE_STATUS = 'UNKNOWN'
    ORDER BY CREATE_TIME
) WHERE ROWNUM <= #{limit,jdbcType=INTEGER}
